use std::{
    env, fs,
    path::{Path, PathBuf},
    process::Command,
    process::ExitCode,
};

fn rust_example(root: &Path, package: &str, example: &str) -> Result<serde_json::Value, String> {
    let target_kind = if package == "acyclic-machines" { "--bin" } else { "--example" };
    let output = Command::new(env::var_os("CARGO_BIN").unwrap_or_else(|| "cargo".into()))
        .args(["run", "--manifest-path", root.join("Cargo.toml").to_str().ok_or("invalid root path")?, "--package", package, target_kind, example, "--no-default-features", "--locked", "--quiet"])
        .current_dir(root)
        .output()
        .map_err(|error| format!("run {package}/{example}: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "run {package}/{example} failed: {}",
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    let line = stdout.lines().rev().find(|line| !line.trim().is_empty())
        .ok_or_else(|| format!("run {package}/{example} produced no JSON"))?;
    serde_json::from_str(line).map_err(|error| format!("parse {package}/{example}: {error}"))
}

fn json(value: &serde_json::Value) -> Result<String, String> {
    serde_json::to_string(value).map_err(|error| error.to_string())
}

fn string(value: &serde_json::Value) -> Result<&str, String> {
    value.as_str().ok_or_else(|| "expected JSON string".to_owned())
}

fn number(value: &serde_json::Value) -> Result<String, String> {
    value.as_u64().map(|value| value.to_string()).ok_or_else(|| "expected non-negative JSON integer".to_owned())
}

fn obj<'a>(value: &'a serde_json::Value, key: &str) -> Result<&'a serde_json::Value, String> {
    value.get(key).ok_or_else(|| format!("missing Rust contract field {key}"))
}

fn array<'a>(value: &'a serde_json::Value, key: &str) -> Result<&'a [serde_json::Value], String> {
    obj(value, key)?.as_array().map(Vec::as_slice).ok_or_else(|| format!("Rust contract field {key} is not an array"))
}

fn generated_header() -> &'static str { "// @generated by Rust sdk-contracts; do not edit.\n\n" }

fn harness_authority(root: &Path, output: &Path, check: bool) -> Result<(), String> {
    let contract = rust_example(root, "acyclic-harness", "authority-id-contract")?;
    let source = format!(
        "{h}const FORBIDDEN_EXACT = new Set({exact});\nconst FORBIDDEN_SEPARATORS = new Set({separators});\nconst CONTROL_RANGES = {ranges} as readonly (readonly [number, number])[];\n\n/** Mirrors Rust Authority::stream_path without requiring asynchronous WASM initialization. */\nexport function isSafeAuthorityId(value: string): boolean {{\n  if (value.length === 0 || FORBIDDEN_EXACT.has(value)) return false;\n  for (const character of value) {{\n    const codePoint = character.codePointAt(0);\n    if (codePoint === undefined || (codePoint >= 0xd800 && codePoint <= 0xdfff) ||\n      FORBIDDEN_SEPARATORS.has(character) ||\n      CONTROL_RANGES.some(([start, end]) => codePoint >= start && codePoint <= end)) return false;\n  }}\n  return true;\n}}\n",
        h = generated_header(), exact = json(obj(&contract, "forbidden_exact")?)?,
        separators = json(obj(&contract, "forbidden_separators")?)?, ranges = json(obj(&contract, "control_ranges")?)?,
    );
    write_or_check(&output.join("typescript/packages/harness/src/authority-contract.ts"), &source, check)
}

