fn harness_component_label(root: &Path, output: &Path, check: bool) -> Result<(), String> {
    let c = rust_example(root, "acyclic-harness", "component-label-contract")?;
    let source = format!(
        "{h}export const COMPONENT_LABEL_MAX_BYTES = {max};\nconst FORBIDDEN_EXACT = new Set({exact});\nconst FORBIDDEN_SEPARATORS = new Set({separators});\nconst INVALID_RANGES = {ranges} as readonly (readonly [number, number])[];\n\n/** Mirrors Rust validate_component_label without requiring asynchronous WASM initialization. */\nexport function isValidComponentLabel(value: string): boolean {{\n  if (value.length === 0 || new TextEncoder().encode(value).byteLength > COMPONENT_LABEL_MAX_BYTES ||\n    FORBIDDEN_EXACT.has(value)) return false;\n  for (const character of value) {{\n    const codePoint = character.codePointAt(0);\n    if (codePoint === undefined || (codePoint >= 0xd800 && codePoint <= 0xdfff) ||\n      FORBIDDEN_SEPARATORS.has(character) ||\n      INVALID_RANGES.some(([start, end]) => codePoint >= start && codePoint <= end)) return false;\n  }}\n  return true;\n}}\n",
        h = generated_header(), max = number(obj(&c,"max_bytes")?)?, exact = json(obj(&c,"forbidden_exact")?)?,
        separators = json(obj(&c,"forbidden_separators")?)?, ranges = json(obj(&c,"invalid_ranges")?)?,
    );
    write_or_check(&output.join("typescript/packages/harness/src/component-label-contract.ts"), &source, check)
}

fn harness_limits(root: &Path, output: &Path, check: bool) -> Result<(), String> {
    let c = rust_example(root, "acyclic-harness", "limits-contract")?;
    let limits = obj(&c, "limits")?;
    let defaults = obj(limits, "default")?;
    let maximum = obj(limits, "maximum")?;
    let limit_fields = ["file_bytes", "path_bytes", "attachments", "render_bytes", "model_steps", "model_events_per_step", "tool_calls_per_step", "context_messages"];
    let field = |value: &serde_json::Value, key: &str| -> Result<String, String> { Ok(format!("{} as number", number(obj(value, key)?)?)) };
    let mut source = String::from("// @generated by Rust sdk-contracts; do not edit.\n\nexport const HARNESS_LIMITS_DEFAULT = Object.freeze({\n");
    for key in limit_fields { source.push_str(&format!("  {}: {},\n", key, field(defaults,key)?)); }
    source.push_str("});\nexport const HARNESS_LIMITS_MAXIMUM = Object.freeze({\n");
    for key in limit_fields { source.push_str(&format!("  {}: {},\n", key, field(maximum,key)?)); }
    source.push_str("});\n");
    for (key, name, bigint) in [("exact_js_integer","HARNESS_MAX_EXACT_JS_INTEGER",false),("max_path_bytes","HARNESS_MAX_PATH_BYTES",false),("max_label_bytes","HARNESS_MAX_LABEL_BYTES",false)] {
        source.push_str(&format!("export const {name} = {};\n", if bigint { format!("{}n",number(limits.get(key).unwrap())?) } else { number(limits.get(key).ok_or_else(||format!("missing {key}"))?)? }));
    }
    source.push_str(&format!("export const HARNESS_MAX_BATCH_INPUTS = {};\n", number(obj(&c,"batch_inputs")?)?));
    source.push_str(&format!("export const HARNESS_MAX_ATTACHMENT_COUNT = {};\n", number(obj(maximum,"attachments")?)?));
    let fork = obj(&c,"fork")?;
    for (key, name, bigint) in [("agents","MAX_FORK_AGENTS",false),("resources","MAX_FORK_RESOURCES",false),("references","MAX_FORK_REFERENCES",false),("attachment_manifest_bytes","MAX_FORK_ATTACHMENT_MANIFEST_BYTES",true),("inherited_bytes","MAX_FORK_INHERITED_BYTES",true),("reference_bytes","MAX_FORK_REFERENCE_BYTES",true),("inherited_messages","MAX_FORK_INHERITED_MESSAGES",true)] {
        let n = number(obj(fork,key)?)?; source.push_str(&format!("export const {name} = {}{};\n", n, if bigint {"n"} else {""}));
    }
    let projection = obj(&c,"projection")?;
    for (key, name, bigint) in [("default_max_resolved_bytes","HARNESS_PROJECTION_DEFAULT_MAX_RESOLVED_BYTES",false),("default_max_manifest_bytes","HARNESS_PROJECTION_DEFAULT_MAX_MANIFEST_BYTES",false),("default_max_attachments","HARNESS_PROJECTION_DEFAULT_MAX_ATTACHMENTS",false),("default_max_messages","HARNESS_PROJECTION_DEFAULT_MAX_MESSAGES",false),("default_max_render_bytes","HARNESS_PROJECTION_DEFAULT_MAX_RENDER_BYTES",false),("max_projected_attachments","HARNESS_PROJECTION_MAX_PROJECTED_ATTACHMENTS",false),("max_json_bytes","HARNESS_PROJECTION_MAX_JSON_BYTES",false)] {
        let n = number(obj(projection,key)?)?; source.push_str(&format!("export const {name} = {}{};\n", n, if bigint {"n"} else {""}));
    }
    write_or_check(&output.join("typescript/packages/harness/src/limits-contract.ts"), &source, check)
}

