fn filesystem_defaults(root: &Path, output: &Path, check: bool) -> Result<(), String> {
    let c = rust_example(root, "acyclic-fs", "filesystem-typescript-defaults")?;
    let volume = obj(&c,"volume_limits")?; let cache = obj(&c,"object_cache_options")?; let hosted = obj(&c,"hosted")?;
    let bigint = ["maximumObjectBytes","maximumReadBytes","maximumFilesPerGeneration","maximumObjectsPerGeneration","maximumGenerationBytes","maximumBytes"];
    fn ordered_keys(value: &serde_json::Value, preferred: &[&str]) -> Result<Vec<String>,String> {
        let map = value.as_object().ok_or_else(||"expected object".to_owned())?;
        let mut keys = preferred.iter().filter(|key| map.contains_key(**key)).map(|key| (*key).to_owned()).collect::<Vec<_>>();
        keys.extend(map.keys().filter(|key| !preferred.contains(&key.as_str())).cloned()); Ok(keys)
    }
    fn render_object(value: &serde_json::Value, bigint: &[&str], indent: usize, preferred: &[&str]) -> Result<String,String> {
        let map = value.as_object().ok_or_else(||"expected object".to_owned())?; let mut out=String::from("Object.freeze({\n");
        for key in ordered_keys(value, preferred)? { let v=&map[&key]; let camel=key.split('_').enumerate().map(|(i,s)| if i==0{s.to_owned()} else { let mut x=s.to_owned(); x[..1].make_ascii_uppercase(); x }).collect::<String>(); let n=if let Some(n)=v.as_u64(){ if bigint.contains(&camel.as_str()){format!("{n}n")}else{n.to_string()} } else { serde_json::to_string(v).map_err(|e|e.to_string())? }; out.push_str(&format!("{}{}: {},\n"," ".repeat(indent),camel,n)); }
        out.push_str(&" ".repeat(indent.saturating_sub(2))); out.push_str("})"); Ok(out)
    }
    fn render_decl_type(key: &str, value: &serde_json::Value, bigint: &[&str], indent: usize) -> Result<String,String> {
        if value.is_string() { Ok("string".to_owned()) }
        else if value.is_number() { Ok(if bigint.contains(&key) { "bigint".to_owned() } else { "number".to_owned() }) }
        else if value.is_object() { render_decl_shape(value, bigint, indent + 2, &[]) }
        else { Err(format!("unsupported declaration value for {key}")) }
    }
    fn render_decl_shape(value: &serde_json::Value, bigint: &[&str], indent: usize, preferred: &[&str]) -> Result<String,String> {
        let map = value.as_object().ok_or_else(||"expected declaration object".to_owned())?; let mut lines=Vec::new();
        for key in ordered_keys(value, preferred)? { let v=&map[&key]; let camel=key.split('_').enumerate().map(|(i,s)| if i==0{s.to_owned()} else { let mut x=s.to_owned(); x[..1].make_ascii_uppercase(); x }).collect::<String>(); lines.push(format!("{}readonly {}: {};"," ".repeat(indent),camel,render_decl_type(&camel,v,bigint,indent)?)); }
        Ok(format!("{{\n{}\n{}}}",lines.join("\n")," ".repeat(indent.saturating_sub(2))))
    }
    let volume_order=["maximum_path_bytes","maximum_component_bytes","maximum_path_depth","maximum_object_bytes","maximum_mutations_per_batch","maximum_paths_per_batch","maximum_checkout_dependencies","maximum_directory_page_entries","maximum_page_height","maximum_read_bytes","maximum_files_per_generation","maximum_objects_per_generation","maximum_generation_bytes"];
    let cache_order=["maximum_entries","maximum_bytes","maximum_in_flight"];
    let hosted_order=["protocol_version","maximum_response_bytes","maximum_page_items","maximum_byte_response_envelope_bytes","minimum_handshake_response_bytes"];
    let source = format!("// @generated by Rust sdk-contracts; do not edit.\n\nexport const DEFAULT_VOLUME_LIMITS = {};\n\nexport const DEFAULT_OBJECT_CACHE_OPTIONS = {};\n\nexport const DEFAULT_HOSTED_OPTIONS = {};\n", render_object(volume,&bigint,2,&volume_order)?, render_object(cache,&bigint,2,&cache_order)?, render_object(hosted,&bigint,2,&hosted_order)?);
    let hosted_shape = render_decl_shape(hosted,&bigint,2,&hosted_order)?;
    let declaration = format!("// @generated by Rust sdk-contracts; do not edit.\n\nimport type {{ NativeObjectCacheOptions, NativeVolumeLimits }} from \"./native/binding.js\";\n\nexport declare const DEFAULT_VOLUME_LIMITS: Readonly<NativeVolumeLimits>;\nexport declare const DEFAULT_OBJECT_CACHE_OPTIONS: Readonly<NativeObjectCacheOptions>;\nexport declare const DEFAULT_HOSTED_OPTIONS: Readonly<{hosted_shape}>;\n");
    write_or_check(&output.join("typescript/packages/filesystem/generated/defaults.js"), &source, check)?;
    write_or_check(&output.join("typescript/packages/filesystem/generated/defaults.d.ts"), &declaration, check)
}

fn filesystem_hosted(root: &Path, output: &Path, check: bool) -> Result<(), String> {
    let c = rust_example(root, "acyclic-fs", "filesystem-typescript-hosted-contract")?;
    let maps = obj(&c,"maps")?;
    let definitions = [
        ("FILESYSTEM_PROFILE_TO_PROFILE","filesystem_profile","FilesystemProfile","FILESYSTEM_PROFILE_"),
        ("FILE_KIND_TO_KIND","file_kind","FileKind","FILE_KIND_"),
        ("MUTATION_STATUS_TO_COMMIT","mutation_status_commit","MutationStatus","MUTATION_STATUS_"),
        ("MUTATION_STATUS_TO_DELETE","mutation_status_delete","MutationStatus","MUTATION_STATUS_"),
        ("JOIN_HISTORY_TO_PUBLIC","join_history","JoinHistory","JOIN_HISTORY_"),
        ("CONFLICT_USE_TO_USAGE","conflict_use","ConflictUse","CONFLICT_USE_"),
        ("SPARSE_TARGET_TO_TARGET","sparse_target","SparseTarget","SPARSE_TARGET_"),
        ("EXTENT_KIND_TO_KIND","extent_kind","ExtentKind","EXTENT_KIND_"),
        ("SOURCE_STATE_TO_STATUS","source_state","SourceState","SOURCE_STATE_"),
        ("SOURCE_INVALIDATION_REASON_TO_REASON","source_invalidation_reason","SourceInvalidationReason","SOURCE_INVALIDATION_REASON_"),
        ("NAME_ENCODING_TO_PUBLIC","name_encoding","NameEncoding","NAME_ENCODING_"),
        ("REBASE_STATUS_TO_STATUS","rebase_status","RebaseStatus","REBASE_STATUS_"),
        ("JOIN_STATUS_TO_STATUS","join_status","JoinStatus","JOIN_STATUS_"),
    ];
    let mut source = String::from("// @generated by Rust sdk-contracts; do not edit.\n\nimport { FilesystemProfile, FileKind, MutationStatus, JoinHistory, ConflictUse, SparseTarget, ExtentKind, SourceState, SourceInvalidationReason, NameEncoding, RebaseStatus, JoinStatus } from \"./proto/filesystem/v2/filesystem_pb.js\";\n\n");
    for (name,key,enum_name,prefix) in definitions { source.push_str(&format!("export const {name} = Object.freeze({{\n")); for entry in array(maps,key)? { let wire=string(obj(entry,"wire")?)?; let suffix=wire.strip_prefix(prefix).ok_or_else(||format!("wire {wire} missing prefix {prefix}"))?; let public_value=obj(entry,"public")?; source.push_str(&format!("  [{enum_name}.{suffix}]: {},\n", if public_value.is_null(){"undefined".to_owned()}else{json(public_value)?})); } source.push_str("});\n\n"); }
    source.push_str("export const JOIN_HISTORY_FROM_PUBLIC = Object.freeze(Object.assign(Object.create(null), {\n"); for entry in array(maps,"join_history")? { if !obj(entry,"public")?.is_null(){ let wire=string(obj(entry,"wire")?)?.strip_prefix("JOIN_HISTORY_").ok_or("invalid join history")?.to_owned(); source.push_str(&format!("  {}: JoinHistory.{wire},\n",json(obj(entry,"public")?)?)); } } source.push_str("}));\n");
    let declaration = format!("{}{}", generated_header(), r#"import type { FilesystemProfile, FileKind, MutationStatus, JoinHistory as WireJoinHistory, ConflictUse, SparseTarget, ExtentKind, SourceState, SourceInvalidationReason as WireSourceInvalidationReason, NameEncoding, RebaseStatus, JoinStatus as WireJoinStatus } from "./proto/filesystem/v2/filesystem_pb.js";
import type { JoinHistory as PublicJoinHistory, SourceInvalidationReason as PublicSourceInvalidationReason, SourceResult, WorkspaceCommitStatus, WorkspaceDeleteStatus, WorkspaceFileKind, WorkspaceRebaseStatus, JoinStatus as PublicJoinStatus, WorkspaceNameEncoding, TransactionDependencyUse, WorkspaceExtentKind, FsProfile } from "../src/contracts.js";

export declare const FILESYSTEM_PROFILE_TO_PROFILE: Readonly<Record<FilesystemProfile, FsProfile | undefined>>;
export declare const FILE_KIND_TO_KIND: Readonly<Record<FileKind, WorkspaceFileKind | undefined>>;
export declare const MUTATION_STATUS_TO_COMMIT: Readonly<Record<MutationStatus, WorkspaceCommitStatus | undefined>>;
export declare const MUTATION_STATUS_TO_DELETE: Readonly<Record<MutationStatus, WorkspaceDeleteStatus | undefined>>;
export declare const JOIN_HISTORY_TO_PUBLIC: Readonly<Record<WireJoinHistory, PublicJoinHistory | undefined>>;
export declare const JOIN_HISTORY_FROM_PUBLIC: Readonly<Record<PublicJoinHistory, WireJoinHistory>>;
export declare const CONFLICT_USE_TO_USAGE: Readonly<Record<ConflictUse, TransactionDependencyUse | undefined>>;
export declare const SPARSE_TARGET_TO_TARGET: Readonly<Record<SparseTarget, "data" | "hole" | undefined>>;
export declare const EXTENT_KIND_TO_KIND: Readonly<Record<ExtentKind, WorkspaceExtentKind | undefined>>;
export declare const SOURCE_STATE_TO_STATUS: Readonly<Record<SourceState, SourceResult["status"] | undefined>>;
export declare const SOURCE_INVALIDATION_REASON_TO_REASON: Readonly<Record<WireSourceInvalidationReason, PublicSourceInvalidationReason | undefined>>;
export declare const NAME_ENCODING_TO_PUBLIC: Readonly<Record<NameEncoding, WorkspaceNameEncoding | undefined>>;
export declare const REBASE_STATUS_TO_STATUS: Readonly<Record<RebaseStatus, WorkspaceRebaseStatus | undefined>>;
export declare const JOIN_STATUS_TO_STATUS: Readonly<Record<WireJoinStatus, PublicJoinStatus | undefined>>;
"#);
    write_or_check(&output.join("typescript/packages/filesystem/generated/hosted-contract.js"), &source, check)?;
    write_or_check(&output.join("typescript/packages/filesystem/generated/hosted-contract.d.ts"), &declaration, check)
}

fn filesystem_git(root: &Path, output: &Path, check: bool) -> Result<(), String> {
    let c = rust_example(root, "acyclic-fs", "filesystem-git-compat-contract")?;
    let strings = |key: &str| -> Result<String,String> { Ok(json(obj(&c,key)?)?) };
    let object = |key: &str| -> Result<String,String> { let mut entries=Vec::new(); for e in array(&c,key)? { let a=e.as_array().ok_or("expected pair")?; entries.push(format!("{}:{}",json(a.first().ok_or("pair key")?)?,json(a.get(1).ok_or("pair value")?)?)); } Ok(format!("{{{}}}",entries.join(","))) };
    let object_fields = |key: &str| -> Result<String,String> { let mut entries=Vec::new(); for e in array(&c,key)? { let a=e.as_object().ok_or("expected field object")?; let name=a.get("key").ok_or("field key")?; let value=a.get("bytes").ok_or("field bytes")?; entries.push(format!("{}:{}",json(name)?,json(value)?)); } Ok(format!("{{{}}}",entries.join(","))) };
    let set = |key: &str| -> Result<String,String> { Ok(format!("new Set({})",strings(key)?)) };
    let source = format!("{h}export const GIT_COMPAT_OUTPUT_VARIANTS = {out};\nexport function isGitCompatOutputVariant(value) {{ return GIT_COMPAT_OUTPUT_VARIANTS.has(value); }}\nexport const GIT_COMPAT_COMMAND_VARIANTS = {cmd};\nexport function isGitCompatCommandVariant(value) {{ return GIT_COMPAT_COMMAND_VARIANTS.has(value); }}\nexport const GIT_COMPAT_ACTION_VARIANTS = {act};\nexport const GIT_COMPAT_RESULT_VARIANTS = {res};\nexport const GIT_COMPAT_RESET_MODE_VARIANTS = {reset};\nexport const GIT_COMPAT_DIRTY_STATE_VARIANTS = {dirty};\nexport const GIT_COMPAT_RESET_MODE_WIRE = Object.freeze({reset_wire});\nexport const GIT_COMPAT_DIRTY_STATE_WIRE = Object.freeze({dirty_wire});\nexport const GIT_COMPAT_IDENTITY_LENGTHS = Object.freeze({identity});\nexport const GIT_COMPAT_BYTE_FIELDS = Object.freeze({bytes});\nexport const GIT_COMPAT_TIMESTAMP_FIELDS = Object.freeze({timestamps});\nexport const GIT_COMPAT_UUID_PATHS = Object.freeze({uuids});\nexport const GIT_COMPAT_OPAQUE_PATHS = Object.freeze({opaque});\nexport const GIT_COMPAT_PUBLIC_ALIASES = Object.freeze({aliases});\nexport const GIT_COMPAT_PENDING_FIELDS = Object.freeze({pending});\nexport const GIT_COMPAT_TRANSITION_IDENTITY_BYTES = {transition};\n", h=generated_header(), out=set("output_variants")?,cmd=set("command_variants")?,act=set("action_variants")?,res=set("result_variants")?,reset=set("reset_mode_typescript_variants")?,dirty=set("dirty_state_typescript_variants")?,reset_wire=object("reset_mode_wire")?,dirty_wire=object("dirty_state_wire")?,identity=object_fields("identity_fields")?,bytes=object_fields("byte_fields")?,timestamps=set("timestamp_fields")?,uuids=set("uuid_paths")?,opaque=set("opaque_paths")?,aliases=object("public_aliases")?,pending=set("pending_fields")?,transition=number(obj(&c,"transition_identity_bytes")?)?);
    let output_variants = array(&c,"output_variants")?.iter().map(json).collect::<Result<Vec<_>,_>>()?.join(" | "); let reset_union=array(&c,"reset_mode_typescript_variants")?.iter().map(json).collect::<Result<Vec<_>,_>>()?.join(" | "); let dirty_union=array(&c,"dirty_state_typescript_variants")?.iter().map(json).collect::<Result<Vec<_>,_>>()?.join(" | ");
    let nested = array(&c,"nested_types")?.iter().map(|e| { let a=e.as_array().ok_or("nested pair")?; Ok(format!("{}\n",string(a.get(1).ok_or("nested declaration")?)?)) }).collect::<Result<String,String>>()?;
    let type_union = |variants_key: &str, types_key: &str| -> Result<String,String> { let variants=array(&c,variants_key)?; let types=array(&c,types_key)?; let mut out=Vec::new(); for variant in variants { let name=string(variant)?; let found=types.iter().find(|entry| entry.as_array().and_then(|a|a.first()).and_then(|v|v.as_str())==Some(name)).ok_or_else(||format!("missing {name}"))?; let a=found.as_array().ok_or("type pair")?; out.push(string(a.get(1).ok_or("type declaration")?)?.to_owned()); } Ok(out.join("\n  | ")) };
    let command_union=type_union("command_variants","command_types")?; let action_union=type_union("action_variants","action_types")?; let result_union=type_union("result_variants","result_types")?; let output_union=type_union("output_variants","output_types")?;
    let identity_fields=array(&c,"identity_fields")?.iter().map(|v| Ok::<String,String>(format!("  readonly {}: {};",json(obj(v,"key")?)?,number(obj(v,"bytes")?)?))).collect::<Result<Vec<_>,_>>()?.join("\n");
    let command_labels=array(&c,"command_variants")?.iter().map(json).collect::<Result<Vec<_>,_>>()?.join(" | "); let action_labels=array(&c,"action_variants")?.iter().map(json).collect::<Result<Vec<_>,_>>()?.join(" | "); let result_labels=array(&c,"result_variants")?.iter().map(json).collect::<Result<Vec<_>,_>>()?.join(" | ");
    let declaration = format!("{h}export type WorkspaceIdentity = Uint8Array;\nexport type GenerationIdentity = Uint8Array;\nexport type OperationIdentity = Uint8Array;\nexport type WorkspaceContextIdentity = Uint8Array;\nexport type WorkspaceRootIdentity = Uint8Array;\nexport type GitCommitIdentity = string;\nexport type GitResetMode = {reset_union};\nexport type GitDirtyState = {dirty_union};\nexport type GitCompatCommand =\n  | {command_union};\n{nested}export type GitFilesystemAction =\n  | {action_union};\nexport type GitFilesystemResult =\n  | {result_union};\nexport interface GitPendingTransition {{ readonly id: OperationIdentity; readonly action: GitFilesystemAction; readonly mutation: unknown; }}\nexport interface GitFilesystemExecutor {{ execute(operationId: OperationIdentity, action: GitFilesystemAction): Promise<GitFilesystemResult>; }}\nexport type GitCompatOutput = \"NoOp\"\n  | {output_union};\nexport interface GitCompatRepository {{ execute(command: GitCompatCommand, workspaceGeneration: GenerationIdentity): Promise<GitCompatOutput>; executeArgv(argv: readonly string[], workspaceGeneration: GenerationIdentity, defaultAuthor: string, nowSeconds: bigint): Promise<GitCompatOutput>; pendingTransition(): Promise<GitPendingTransition | undefined>; completeTransition(transition: OperationIdentity, resultingGeneration?: GenerationIdentity): Promise<GitCompatOutput>; completeTransitionResult(transition: OperationIdentity, result: GitFilesystemResult): Promise<GitCompatOutput>; run(command: GitCompatCommand, workspaceGeneration: GenerationIdentity, executor: GitFilesystemExecutor): Promise<GitCompatOutput>; runArgv(argv: readonly string[], workspaceGeneration: GenerationIdentity, defaultAuthor: string, nowSeconds: bigint, executor: GitFilesystemExecutor): Promise<GitCompatOutput>; resume(executor: GitFilesystemExecutor): Promise<GitCompatOutput | undefined>; abortTransition(transition: OperationIdentity): Promise<void>; registerBranchWorkspace(branch: string, workspaceId: WorkspaceIdentity, head: GitCommitIdentity | undefined, switchToBranch: boolean): Promise<GitCompatOutput>; recordCommit(expectedHead: GitCommitIdentity | undefined, generation: GenerationIdentity, trackedPaths: readonly string[], message: string, author: string, authoredAtSeconds: bigint): Promise<GitCompatOutput>; }}\nexport declare const GIT_COMPAT_OUTPUT_VARIANTS: ReadonlySet<{output_variants}>;\nexport declare function isGitCompatOutputVariant(value: string): boolean;\nexport declare const GIT_COMPAT_COMMAND_VARIANTS: ReadonlySet<{command_labels}>;\nexport declare function isGitCompatCommandVariant(value: string): boolean;\nexport declare const GIT_COMPAT_ACTION_VARIANTS: ReadonlySet<{action_labels}>;\nexport declare const GIT_COMPAT_RESULT_VARIANTS: ReadonlySet<{result_labels}>;\nexport declare const GIT_COMPAT_RESET_MODE_VARIANTS: ReadonlySet<{reset_union}>;\nexport declare const GIT_COMPAT_DIRTY_STATE_VARIANTS: ReadonlySet<{dirty_union}>;\nexport declare const GIT_COMPAT_RESET_MODE_WIRE: Readonly<Record<GitResetMode, string>>;\nexport declare const GIT_COMPAT_DIRTY_STATE_WIRE: Readonly<Record<GitDirtyState, string>>;\nexport declare const GIT_COMPAT_IDENTITY_LENGTHS: Readonly<{{\n{identity_fields}\n}}>;\nexport declare const GIT_COMPAT_BYTE_FIELDS: Readonly<Record<string, number | null>>;\nexport declare const GIT_COMPAT_TIMESTAMP_FIELDS: ReadonlySet<string>;\nexport declare const GIT_COMPAT_UUID_PATHS: ReadonlySet<string>;\nexport declare const GIT_COMPAT_OPAQUE_PATHS: ReadonlySet<string>;\nexport declare const GIT_COMPAT_PUBLIC_ALIASES: Readonly<Record<string, string>>;\nexport declare const GIT_COMPAT_PENDING_FIELDS: ReadonlySet<string>;\nexport declare const GIT_COMPAT_TRANSITION_IDENTITY_BYTES: {transition};\n",h=generated_header(),reset_union=reset_union,dirty_union=dirty_union,nested=nested,command_union=command_union,action_union=action_union,result_union=result_union,output_union=output_union,output_variants=output_variants,command_labels=command_labels,action_labels=action_labels,result_labels=result_labels,identity_fields=identity_fields,transition=number(obj(&c,"transition_identity_bytes")?)?);
    write_or_check(&output.join("typescript/packages/filesystem/generated/git-compat-contract.js"), &source, check)?; write_or_check(&output.join("typescript/packages/filesystem/generated/git-compat-contract.d.ts"), &declaration, check)
}

const INFERENCE_DEFAULTS_SOURCE: &str =
    "// @generated by Rust sdk-contracts; do not edit.\n\n";
const TERMINAL_HEADER: &str =
    "// @generated by Rust sdk-contracts; do not edit.\n\n";
const FIXED_WIDTH_HEADER: &str =
    "// @generated by Rust sdk-contracts; do not edit.\n\n";
const STREAM_TOKEN_HEADER: &str =
    "// @generated by Rust sdk-contracts; do not edit.\n\n";
const STREAM_HTTP_HEADER: &str =
    "// @generated by Rust sdk-contracts; do not edit.\n\n";

fn write_or_check(path: &Path, content: &str, check: bool) -> Result<(), String> {
    if check {
        let current = fs::read_to_string(path)
            .map_err(|error| format!("read {}: {error}", path.display()))?;
        if current != content {
            return Err(format!("Rust-generated contract drift: {}", path.display()));
        }
    } else {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)
                .map_err(|error| format!("create {}: {error}", parent.display()))?;
        }
        fs::write(path, content).map_err(|error| format!("write {}: {error}", path.display()))?;
    }
    Ok(())
}

fn inference(_root: &Path, output: &Path, check: bool) -> Result<(), String> {
    let defaults_js = format!(
        "{INFERENCE_DEFAULTS_SOURCE}export const MAXIMUM_MESSAGE_BYTES = {};\nexport const MAXIMUM_HTTP_JSON_BYTES = {};\n",
        acyclic_inference::MAXIMUM_MESSAGE_BYTES,
        acyclic_inference::MAXIMUM_HTTP_JSON_BYTES,
    );
    let defaults_dts = format!(
        "{INFERENCE_DEFAULTS_SOURCE}export declare const MAXIMUM_MESSAGE_BYTES: number;\nexport declare const MAXIMUM_HTTP_JSON_BYTES: number;\n"
    );
    let terminal = acyclic_inference_wasm::run_terminal_metadata_native().map_err(str::to_owned)?;
    let terminal_items: Vec<serde_json::Value> =
        serde_json::from_str(&terminal).map_err(|error| format!("terminal metadata: {error}"))?;
    if terminal_items.is_empty() {
        return Err("terminal metadata is empty".to_owned());
    }
    let terminal_js = format!(
        "{TERMINAL_HEADER}export const RUN_TERMINAL_METADATA = Object.freeze([\n{}\n]);\n",
        terminal_items
            .iter()
            .map(|item| {
                let number = item
                    .get("number")
                    .and_then(serde_json::Value::as_i64)
                    .unwrap_or_default();
                let kind = item
                    .get("kind")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default();
                let partial = item
                    .get("partial")
                    .and_then(serde_json::Value::as_bool)
                    .unwrap_or(false);
                format!(
                    r#"  Object.freeze({{"number":{number},"kind":"{kind}","partial":{partial}}})"#
                )
            })
            .collect::<Vec<_>>()
            .join(",\n")
    );
    let kinds = terminal_items
        .iter()
        .filter_map(|item| {
            item.get("kind")
                .and_then(serde_json::Value::as_str)
                .map(|kind| format!("{kind:?}"))
        })
        .collect::<Vec<_>>()
        .join(" | ");
    let terminal_dts = format!(
        "{TERMINAL_HEADER}export type RunTerminalKind = {kinds};\nexport interface RunTerminalMetadata {{\n  readonly number: number;\n  readonly kind: RunTerminalKind;\n  readonly partial: boolean;\n}}\nexport declare const RUN_TERMINAL_METADATA: readonly RunTerminalMetadata[];\n"
    );
    let fixed = acyclic_inference_wasm::fixed_width_metadata_native().map_err(str::to_owned)?;
    let fixed_items: Vec<serde_json::Value> =
        serde_json::from_str(&fixed).map_err(|error| format!("fixed-width metadata: {error}"))?;
    if fixed_items.is_empty() {
        return Err("fixed-width metadata is empty".to_owned());
    }
    let fixed_js = format!(
        "{FIXED_WIDTH_HEADER}export const INFERENCE_FIXED_WIDTH_METADATA = Object.freeze([\n{}\n]);\n",
        fixed_items
            .iter()
            .map(|item| {
                let message = item.get("message").and_then(serde_json::Value::as_str).unwrap_or_default();
                let field = item.get("field").and_then(serde_json::Value::as_str).unwrap_or_default();
                let width = item.get("width").and_then(serde_json::Value::as_u64).unwrap_or_default();
                format!(r#"  Object.freeze({{"message":"{message}","field":"{field}","width":{width}}})"#)
            })
            .collect::<Vec<_>>()
            .join(",\n")
    );
    let fixed_dts = "// @generated by Rust sdk-contracts; do not edit.\n\nexport interface InferenceFixedWidthMetadata {\n  readonly message: string;\n  readonly field: string;\n  readonly width: number;\n}\nexport declare const INFERENCE_FIXED_WIDTH_METADATA: readonly InferenceFixedWidthMetadata[];\n";
    write_or_check(&output.join("defaults.js"), &defaults_js, check)?;
    write_or_check(&output.join("defaults.d.ts"), &defaults_dts, check)?;
    write_or_check(&output.join("terminal-metadata.js"), &terminal_js, check)?;
    write_or_check(&output.join("terminal-metadata.d.ts"), &terminal_dts, check)?;
    write_or_check(&output.join("fixed-width-metadata.js"), &fixed_js, check)?;
    write_or_check(&output.join("fixed-width-metadata.d.ts"), fixed_dts, check)?;
    Ok(())
}

fn stream(_root: &Path, output: &Path, check: bool) -> Result<(), String> {
    let operations = serde_json::to_string(acyclic_stream::TOKEN_OPERATIONS)
        .map_err(|error| format!("token operations: {error}"))?
        .replace(',', ", ");
    let operations_ts = format!(
        "{STREAM_TOKEN_HEADER}export const TOKEN_OPERATIONS = {operations} as const;\nexport type TokenOperation = (typeof TOKEN_OPERATIONS)[number];\n"
    );
    let routes = acyclic_stream::HTTP_RESPONSE_CONTRACT
        .iter()
        .map(|(route, kind)| format!("  {route:?}: {kind:?},"))
        .collect::<Vec<_>>()
        .join("\n");
    let http_ts = format!(
        "{STREAM_HTTP_HEADER}import {{ decodeHttpResponse as decodeHttpResponseWasm }} from \"../generated/wasm/acyclic_stream_wasm.js\";\nimport type {{\n  AccessToken, AppendResult, ChildrenPage, CommittedEnvelope, EncodedRecord, ForkReceipt,\n  IdempotencyObservation, CommitResult, Sequence,\n}} from \"./types.js\";\n\nexport const HTTP_RESPONSE_CONTRACT = Object.freeze({{\n{routes}\n}} as const);\n\nexport type HttpRoute = keyof typeof HTTP_RESPONSE_CONTRACT;\n\ntype HttpResponseByKind = {{\n  observation: IdempotencyObservation | undefined;\n  sequence: Sequence;\n  append: AppendResult;\n  fork: ForkReceipt;\n  records: readonly EncodedRecord[];\n  children: readonly {{ readonly path: string }}[];\n  children_page: ChildrenPage;\n  commit: CommitResult;\n  envelope: CommittedEnvelope;\n  token: AccessToken;\n}};\n\nexport type HttpResponseFor<Route extends HttpRoute> =\n  HttpResponseByKind[typeof HTTP_RESPONSE_CONTRACT[Route]];\n\n/**\n * Decode one Rust-validated hosted response with the route-specific public\n * result type derived from the canonical route/family table above.\n *\n * The implementation intentionally remains unknown at this boundary: the\n * Rust/WASM decoder owns runtime validation and projection, while these\n * overloads carry its generated route association into the TypeScript API.\n */\nexport function decodeHttpResponseFor<Route extends HttpRoute>(\n  route: Route,\n  responseJson: string,\n): HttpResponseFor<Route>;\nexport function decodeHttpResponseFor(route: string, responseJson: string): unknown {{\n  return decodeHttpResponseWasm(route, responseJson);\n}}\n"
    );
    write_or_check(&output.join("token-operations.ts"), &operations_ts, check)?;
    write_or_check(&output.join("http-contract.ts"), &http_ts, check)?;
    Ok(())
}

fn main() -> ExitCode {
    let mut args = env::args_os().skip(1);
    let mode = args
        .next()
        .and_then(|value| value.into_string().ok())
        .unwrap_or_default();
    let root = args
        .next()
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));
    let output = args
        .next()
        .map(PathBuf::from)
        .unwrap_or_else(|| root.clone());
    let result = match mode.as_str() {
        "inference-write" => inference(&root, &output.join("typescript/packages/inference/generated"), false),
        "inference-check" => inference(&root, &output.join("typescript/packages/inference/generated"), true),
        "stream-write" => stream(&root, &output.join("typescript/packages/stream/src"), false),
        "stream-check" => stream(&root, &output.join("typescript/packages/stream/src"), true),
        "filesystem-defaults-write" => filesystem_defaults(&root, &output, false),
        "filesystem-defaults-check" => filesystem_defaults(&root, &output, true),
        "filesystem-git-write" => filesystem_git(&root, &output, false),
        "filesystem-git-check" => filesystem_git(&root, &output, true),
        "filesystem-hosted-write" => filesystem_hosted(&root, &output, false),
        "filesystem-hosted-check" => filesystem_hosted(&root, &output, true),
        "harness-authority-write" => harness_authority(&root, &output, false),
        "harness-authority-check" => harness_authority(&root, &output, true),
        "harness-child-page-write" => harness_child_page(&root, &output, false),
        "harness-child-page-check" => harness_child_page(&root, &output, true),
        "harness-component-label-write" => harness_component_label(&root, &output, false),
        "harness-component-label-check" => harness_component_label(&root, &output, true),
        "harness-conversation-page-write" => harness_conversation_page(&root, &output, false),
        "harness-conversation-page-check" => harness_conversation_page(&root, &output, true),
        "harness-limits-write" => harness_limits(&root, &output, false),
        "harness-limits-check" => harness_limits(&root, &output, true),
        "harness-private-directory-write" => harness_private_page(&root, &output, false),
        "harness-private-directory-check" => harness_private_page(&root, &output, true),
        "machines-managed-oci-write" => machines_managed_oci(&root, &output, false),
        "machines-managed-oci-check" => machines_managed_oci(&root, &output, true),
        "all-write" => {
            filesystem_defaults(&root,&output,false).and_then(|_| filesystem_git(&root,&output,false)).and_then(|_| filesystem_hosted(&root,&output,false)).and_then(|_| harness_authority(&root,&output,false)).and_then(|_| harness_child_page(&root,&output,false)).and_then(|_| harness_component_label(&root,&output,false)).and_then(|_| harness_conversation_page(&root,&output,false)).and_then(|_| harness_limits(&root,&output,false)).and_then(|_| harness_private_page(&root,&output,false)).and_then(|_| machines_managed_oci(&root,&output,false))
        }
        "all-check" => {
            filesystem_defaults(&root,&output,true).and_then(|_| filesystem_git(&root,&output,true)).and_then(|_| filesystem_hosted(&root,&output,true)).and_then(|_| harness_authority(&root,&output,true)).and_then(|_| harness_child_page(&root,&output,true)).and_then(|_| harness_component_label(&root,&output,true)).and_then(|_| harness_conversation_page(&root,&output,true)).and_then(|_| harness_limits(&root,&output,true)).and_then(|_| harness_private_page(&root,&output,true)).and_then(|_| machines_managed_oci(&root,&output,true))
        }
        _ => Err("usage: sdk-contracts <family-write|family-check|all-write|all-check> [repo-root] [output-root]".to_owned()),
    };
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("{error}");
            ExitCode::FAILURE
        }
    }
}
